use std::sync::{Arc, Mutex};
use std::collections::HashMap;

/// Account balance management system with fee processing
/// All arithmetic uses checked/saturating operations for safety

#[derive(Debug, Clone)]
pub struct Account {
    pub id: u64,
    pub available_balance: u64,
    pub pending_holds: u64,
    pub fee_credits: i64,  // Can be negative (owed fees) or positive (credits)
}

impl Account {
    pub fn effective_balance(&self) -> u64 {
        // Available minus holds, adjusted by fee credits
        let base = self.available_balance.saturating_sub(self.pending_holds);
        if self.fee_credits >= 0 {
            base.saturating_add(self.fee_credits as u64)
        } else {
            base.saturating_sub(self.fee_credits.unsigned_abs())
        }
    }

    pub fn can_withdraw(&self, amount: u64) -> bool {
        self.effective_balance() >= amount
    }
}

#[derive(Debug)]
pub struct TransferEngine {
    accounts: Arc<Mutex<HashMap<u64, Account>>>,
    fee_schedule: FeeSchedule,
}

#[derive(Debug, Clone)]
pub struct FeeSchedule {
    pub base_fee_bps: u32,       // basis points
    pub priority_fee_flat: u64,  // flat fee in cents
    pub monthly_maintenance: u64,
}

impl FeeSchedule {
    pub fn calculate_transfer_fee(&self, amount: u64, is_priority: bool) -> u64 {
        let bps_fee = (amount as u128 * self.base_fee_bps as u128 / 10000u128) as u64;
        if is_priority {
            bps_fee.saturating_add(self.priority_fee_flat)
        } else {
            bps_fee
        }
    }
}

#[derive(Debug)]
pub enum TransferError {
    InsufficientFunds,
    AccountNotFound,
    InvalidAmount,
    SameAccount,
}

impl TransferEngine {
    pub fn new(fee_schedule: FeeSchedule) -> Self {
        Self {
            accounts: Arc::new(Mutex::new(HashMap::new())),
            fee_schedule,
        }
    }

    pub fn create_account(&self, id: u64, initial_balance: u64) {
        let mut accounts = self.accounts.lock().unwrap();
        accounts.insert(id, Account {
            id,
            available_balance: initial_balance,
            pending_holds: 0,
            fee_credits: 0,
        });
    }

    /// Process a transfer between accounts with fee assessment
    /// Security: validates sufficient funds including fees before executing
    pub fn execute_transfer(
        &self,
        from_id: u64,
        to_id: u64,
        amount: u64,
        is_priority: bool,
    ) -> Result<u64, TransferError> {
        if amount == 0 {
            return Err(TransferError::InvalidAmount);
        }
        if from_id == to_id {
            return Err(TransferError::SameAccount);
        }

        let fee = self.fee_schedule.calculate_transfer_fee(amount, is_priority);
        let mut accounts = self.accounts.lock().unwrap();

        let from_account = accounts.get(&from_id)
            .ok_or(TransferError::AccountNotFound)?;

        // Validate the sender can cover BOTH the transfer amount AND the fee
        // We check against effective_balance with fee already considered
        let total_required = amount.saturating_add(fee);
        if !from_account.can_withdraw(total_required) {
            return Err(TransferError::InsufficientFunds);
        }

        // Ensure the recipient exists BEFORE mutating the sender, so a
        // missing recipient cannot leave the sender debited (no partial state).
        if !accounts.contains_key(&to_id) {
            return Err(TransferError::AccountNotFound);
        }

        // Deduct transfer amount and apply fee atomically
        let from_account = accounts.get_mut(&from_id).unwrap();
        from_account.available_balance = from_account.available_balance.saturating_sub(amount);
        from_account.fee_credits = from_account.fee_credits.saturating_sub(fee as i64);

        // Credit the recipient (existence already validated above)
        let to_account = accounts.get_mut(&to_id).unwrap();
        to_account.available_balance = to_account.available_balance.saturating_add(amount);

        Ok(fee)
    }

    /// Batch fee assessment for monthly maintenance
    pub fn assess_monthly_fees(&self) {
        let mut accounts = self.accounts.lock().unwrap();
        let maintenance = self.fee_schedule.monthly_maintenance;
        for (_, account) in accounts.iter_mut() {
            account.fee_credits = account.fee_credits.saturating_sub(maintenance as i64);
        }
    }

    pub fn get_balance(&self, id: u64) -> Option<u64> {
        let accounts = self.accounts.lock().unwrap();
        accounts.get(&id).map(|a| a.effective_balance())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_transfer() {
        let engine = TransferEngine::new(FeeSchedule {
            base_fee_bps: 50,  // 0.5%
            priority_fee_flat: 500,
            monthly_maintenance: 1000,
        });
        engine.create_account(1, 100_000);
        engine.create_account(2, 50_000);

        let fee = engine.execute_transfer(1, 2, 10_000, false).unwrap();
        assert_eq!(fee, 50); // 0.5% of 10000
    }

    #[test]
    fn test_insufficient_funds_with_fee() {
        let engine = TransferEngine::new(FeeSchedule {
            base_fee_bps: 50,
            priority_fee_flat: 500,
            monthly_maintenance: 1000,
        });
        engine.create_account(1, 1_000);
        engine.create_account(2, 0);

        // Even though 1000 >= 999, the fee makes total > balance
        let result = engine.execute_transfer(1, 2, 999, true);
        assert!(result.is_err());
    }
}
